/* Explicit dimensions plus two independent round masks keep every image corner hidden. */
.piece{width:14.666667%;aspect-ratio:1;height:auto}.orb{position:absolute;inset:0;width:auto;height:auto;overflow:hidden;border-radius:50%;border:var(--piece-frame-width) solid var(--piece-frame);background:white;padding:0;box-shadow:0 1px 2px #9577aa28;isolation:isolate;clip-path:circle(50%)}
