/* v1.3.0: uniform jelly response; artwork is never stretched on a single axis. */
.piece .orb{scale:var(--puff-scale,1);transition:scale .10s ease-out;box-shadow:0 2px 4px #8f71a32c,inset 0 1px 2px #fff9}
.piece .orb::after{content:'';position:absolute;inset:1px;border-radius:50%;pointer-events:none;z-index:2;background:radial-gradient(ellipse at 32% 5%,#ffffff55 0%,#ffffff13 24%,transparent 49%);box-shadow:inset 0 1px 2px #ffffffa6,inset 0 -1px 2px #9878a815}
.piece .art-mask img{object-fit:contain}
.piece.selected .orb{scale:1.08;box-shadow:0 0 0 2px #fff,0 0 12px #ed91b8}
.piece.candidate::after{content:'';position:absolute;inset:-2px;border-radius:50%;pointer-events:none;border:2px solid #91d8c4;box-shadow:0 0 8px #c3f4de,0 0 0 1px #ffffffbf;animation:next-glow 1.05s ease-in-out infinite}
.piece.candidate .orb{border-color:#b4e8d3}
