@keyframes jelly-pop{0%{scale:1;opacity:1}35%{scale:.84;opacity:1}60%{scale:1.08;opacity:.9}100%{scale:0;opacity:0}}
@media(prefers-reduced-motion:reduce){.piece .orb{scale:1;transition:none}.piece.selected .orb{scale:1.03}.piece.candidate::after{animation:none;opacity:.85}}
