.piece.selected .orb{border:0;padding:0;scale:1.045;box-shadow:none}
.piece.selected::after{content:'';position:absolute;inset:-3px;pointer-events:none;border:2px solid #e97eae;border-radius:50%;box-shadow:0 0 7px #f3bad1}
.piece.candidate .orb{border:0}
.shuffle-area{text-align:center;margin-top:17px}.shuffle-button{min-width:190px;min-height:47px;padding:10px 22px;border-radius:18px;font-size:13px;background:linear-gradient(#f7efff,#e8daf6);box-shadow:0 4px 0 #d3bee4}.shuffle-button:disabled{opacity:.68;cursor:default}.shuffle-button.ready{color:#b96795;border-color:#fff;background:linear-gradient(#ffe7f1,#f4bed5);box-shadow:0 4px 0 #dda0bb;animation:shuffle-ready 1.3s ease-in-out infinite}#shuffleHint{font-size:10px;line-height:1.5;color:#a38aac;min-height:15px;margin:8px 0 0}.shuffle-area:has(.ready) #shuffleHint{color:#bb739c}
#board.shuffle-out .piece .orb{animation:shuffle-hide .16s ease-in forwards}#board.shuffle-in .piece .orb{animation:shuffle-show .24s ease-out both}
@keyframes shuffle-ready{50%{filter:brightness(1.05);box-shadow:0 4px 0 #dda0bb,0 0 12px #edb4cf66}}
@keyframes shuffle-hide{to{scale:.72;opacity:0}}
@keyframes shuffle-show{0%{scale:.72;opacity:0}70%{scale:1.045;opacity:1}100%{scale:1;opacity:1}}
@media(prefers-reduced-motion:reduce){.piece .orb::before,.piece .orb::after{transform:none;transition:none}.piece .orb .art-mask{transform:none;transition:none}.shuffle-button.ready{animation:none}}

/* v1.5.0: unobscured, image-independent connection feedback */
.play-settings{justify-content:center}
.piece.subdued{opacity:.68}
.piece.selected{z-index:5;filter:drop-shadow(0 0 5px #ff73ae)}
.piece.selected .orb{transform:scale(1.085)}
.piece.candidate{z-index:4;filter:drop-shadow(0 0 6px #5de5bc)}
.piece.candidate::after{border:4px solid #e6fff5!important;box-shadow:0 0 0 3px #45cfa8,0 0 18px 7px #84ffd2;opacity:1;animation:connection-glow 1.3s ease-in-out infinite}
.piece.idle-hint{z-index:3}
.piece.idle-hint::after{content:"";position:absolute;inset:-4px;border:3px solid #fff5ad;border-radius:50%;box-shadow:0 0 0 2px #edb95d,0 0 15px 4px #ffeeb1;pointer-events:none;animation:connection-glow 2s ease-in-out infinite}
@keyframes connection-glow{50%{opacity:.65;filter:brightness(1.15)}}
.shuffle-button.ready{animation:none}
.shuffle-button:active{transform:translateY(3px) scale(.96)}
@media(prefers-reduced-motion:reduce){.piece.candidate::after,.piece.idle-hint::after{animation:none}}
